export const HERO_VIDEO_B64 = HERO_VIDEO_B64_PART1 + HERO_VIDEO_B64_PART2;

export function resolveLogoSrc(src?: string): string {
  if (!src || src.includes("GCDIS_HD_Logo")) {
    return GCDIS_LOGO_DATA_URL;
  }
  if (src.includes("Galgotias-University-Logo")) {
    return GALGOTIAS_UNIVERSITY_LOGO_DATA_URL;
  }
  return src;
}

let cachedHeroBlobUrl: string | null = null;

export function getHeroVideoBlobUrl(): string {
  if (cachedHeroBlobUrl) return cachedHeroBlobUrl;
  try {
    const binStr = atob(HERO_VIDEO_B64);
    const bytes = new Uint8Array(binStr.length);
    for (let i = 0; i < binStr.length; i++) {
      bytes[i] = binStr.charCodeAt(i);
    }
    const blob = new Blob([bytes], { type: "video/mp4" });
    cachedHeroBlobUrl = URL.createObjectURL(blob);
    return cachedHeroBlobUrl;
  } catch {
    return "/assets/aistudio/hero-drone-soccer_5297df9b.mp4";
  }
}
